var documenterSearchIndex = {"docs":
[{"category":"section","location":"running/installation/#Installation","page":"Installation","text":"NeuralCrop.jl is currently installed from GitHub:\n\npkg> add https://github.com/yunan-l/NeuralCrop.jl.git\n\nFor local development:\n\ngit clone https://github.com/yunan-l/NeuralCrop.jl.git\ncd NeuralCrop.jl\njulia --project=. -e \"import Pkg; Pkg.instantiate()\"\n\nThe package is developed for Julia 1.10.x.","title":"Installation"},{"category":"section","location":"running/installation/#Reproducibility","page":"Installation","text":"The repository provides Project.toml, which records direct dependencies and compatibility constraints. To reproduce an exact package environment for a publication or experiment, keep the generated Manifest.toml together with the corresponding repository commit.","title":"Reproducibility"},{"category":"section","location":"running/installation/#GPU-support","page":"Installation","text":"NeuralCrop uses CUDA, LuxCUDA, Adapt, and KernelAbstractions for GPU-capable workflows. A CUDA-capable system is required for GPU execution; CPU execution remains useful for development and smaller examples.","title":"GPU support"},{"category":"section","location":"references/#References","page":"References","text":"If you use NeuralCrop.jl in research or other non-commercial activities, please cite:\n\n@article{lin2025neuralcrop,\n  title={NeuralCrop: Combining physics and machine learning for improved crop yield projections},\n  author={Lin, Yunan and Bathiany, Sebastian and Badri, Maha and Gelbrecht, Maximilian and Hess, Philipp and Groenke, Brian and Heinke, Jens and M{\\\"u}ller, Christoph and Boers, Niklas},\n  journal={arXiv preprint arXiv:2512.20177},\n  year={2025}\n}","title":"References"},{"category":"section","location":"references/#Related-resources","page":"References","text":"NeuralCrop.jl source repository: https://github.com/yunan-l/NeuralCrop.jl\nLPJmL reference model: https://gmd.copernicus.org/articles/11/2789/2018/\nISIMIP data repository: https://data.isimip.org/","title":"Related resources"},{"category":"section","location":"models/soil_model/#Soil-model","page":"Soil model","text":"The soil model contains water, carbon, nitrogen, temperature, and snow-related state variables. Soil arrays are generally organized by soil layer and grid cell.","title":"Soil model"},{"category":"section","location":"models/soil_model/#Water","page":"Soil model","text":"Soil water routines compute infiltration, percolation, evapotranspiration-related fluxes, runoff, free water, and layer water content.","title":"Water"},{"category":"section","location":"models/soil_model/#Biogeochemistry","page":"Soil model","text":"Soil carbon and nitrogen routines update litter, fast, and slow pools. Tillage and crop residue inputs affect carbon and nitrogen transfers between pools.","title":"Biogeochemistry"},{"category":"section","location":"models/soil_model/#Temperature-and-snow","page":"Soil model","text":"The model includes snow updates and a simplified lagged soil-temperature method. Soil temperature influences crop and soil process rates.","title":"Temperature and snow"},{"category":"section","location":"contributing/#Contributing","page":"Contributing","text":"Contributions are welcome. NeuralCrop is an active research codebase, and clear, focused contributions help a lot.","title":"Contributing"},{"category":"section","location":"contributing/#Development-setup","page":"Contributing","text":"git clone https://github.com/yunan-l/NeuralCrop.jl.git\ncd NeuralCrop.jl\njulia --project=. -e \"import Pkg; Pkg.instantiate()\"\n\nFor documentation work:\n\njulia --project=docs -e \"import Pkg; Pkg.instantiate()\"\njulia --project=docs docs/make.jl","title":"Development setup"},{"category":"section","location":"contributing/#Contribution-guidelines","page":"Contributing","text":"Keep pull requests focused on one theme.\nPrefer small, composable functions and in-place updates in performance-sensitive loops.\nPreserve array shape conventions and device-compatibility patterns.\nUpdate docs when behavior or public interfaces change.\nInclude tests for new behavior when feasible.","title":"Contribution guidelines"},{"category":"section","location":"contributing/#Suggested-PR-structure","page":"Contributing","text":"Problem statement and motivation.\nSummary of design choices.\nValidation: tests, comparisons, or diagnostics.\nNotes on numerical stability and performance implications.","title":"Suggested PR structure"},{"category":"section","location":"contributing/#Questions-and-contact","page":"Contributing","text":"For collaboration and usage questions, please open an issue in the repository or contact the maintainers listed in the project README.","title":"Questions and contact"},{"category":"section","location":"models/crop_model/#Crop-model","page":"Crop model","text":"The crop model represents crop phenology, photosynthesis, leaf area, carbon allocation, respiration, nitrogen demand, nitrogen uptake, transpiration, interception, management, and harvest.","title":"Crop model"},{"category":"section","location":"models/crop_model/#C3-and-C4-pathways","page":"Crop model","text":"NeuralCrop provides separate daily drivers for C3 and C4 crops. The main difference is the photosynthesis pathway used during the daily crop physiology step.","title":"C3 and C4 pathways"},{"category":"section","location":"models/crop_model/#Management-callbacks","page":"Crop model","text":"Sowing, fertilization, and harvesting are handled through crop calendar and management state. The crop state is initialized or reset on sowing and harvest days.","title":"Management callbacks"},{"category":"section","location":"models/crop_model/#Outputs","page":"Crop model","text":"Crop diagnostics include LAI, biomass, yield, GPP, respiration, vegetation carbon pools, phenological state, water stress, nitrogen stress, and harvest masks.","title":"Outputs"},{"category":"section","location":"processes/crop/overview/#Crop-processes","page":"Overview","text":"Crop processes convert daily forcing and soil state into crop growth, stress, carbon gain, nitrogen dynamics, water use, and harvest output.\n\nThe daily crop order is approximately:\n\nRead climate and update snow.\nApply cultivation and fertilizer management.\nUpdate climate buffers, albedo, radiation, and soil temperature.\nUpdate phenology and harvest state.\nCompute photosynthesis and crop carbon.\nUpdate nitrogen allocation and uptake.\nCompute interception, transpiration, and evaporation.","title":"Crop processes"},{"category":"section","location":"processes/crop/phenology_management/#Phenology-and-management","page":"Phenology and management","text":"Phenology and management determine when crops are planted, how they progress through growing stages, and when carbon and nitrogen pools are reset or transferred at harvest.","title":"Phenology and management"},{"category":"section","location":"processes/crop/phenology_management/#Phenology","page":"Phenology and management","text":"Phenology routines accumulate heat and vernalization-related quantities to track crop development.","title":"Phenology"},{"category":"section","location":"processes/crop/phenology_management/#Cultivation","page":"Phenology and management","text":"cultivate! initializes crop variables on sowing days and applies management inputs such as fertilizer and manure.","title":"Cultivation"},{"category":"section","location":"processes/crop/phenology_management/#Harvest","page":"Phenology and management","text":"harvest_crop! handles harvest timing, yield output, residue transfers, and calendar bookkeeping.","title":"Harvest"},{"category":"section","location":"running/daily_simulations/#Daily-simulations","page":"Daily simulations","text":"Daily simulations are driven by daily_crop_C3! and daily_crop_C4!. Both functions update model state in place over a range of days.","title":"Daily simulations"},{"category":"section","location":"running/daily_simulations/#Process-based-simulation","page":"Daily simulations","text":"The process-based methods call explicit crop and soil routines for photosynthesis, respiration, carbon allocation, nitrogen demand and uptake, evapotranspiration, soil water, soil carbon, and soil nitrogen.","title":"Process-based simulation"},{"category":"section","location":"running/daily_simulations/#Hybrid-simulation","page":"Daily simulations","text":"Hybrid methods accept a model, parameters, and states for neural-network components. These components can replace selected process calculations such as soil water, soil carbon, soil nitrogen, or crop carbon related terms.","title":"Hybrid simulation"},{"category":"section","location":"running/daily_simulations/#Output","page":"Daily simulations","text":"Outputs are written into preallocated Output containers. Common diagnostics include GPP, LAI, biomass, yield, respiration, soil water, vegetation carbon, litter carbon, fast carbon, slow carbon, and harvest masks.","title":"Output"},{"category":"section","location":"extending/core_interfaces/#Core-interfaces","page":"Core interfaces","text":"NeuralCrop is organized around a small set of interface boundaries that make extension manageable:\n\nData loaders produce model-ready named tuples for climate, crop management, soil parameters, and initial states.\nInitialization routines allocate and populate mutable state containers on the chosen device.\nDaily drivers (daily_crop_C3!, daily_crop_C4!) orchestrate process calls in a fixed daily update order.\nProcess modules update specific parts of state in place.\nOutput routines store diagnostics for training and analysis.","title":"Core interfaces"},{"category":"section","location":"extending/core_interfaces/#State-first-extension-pattern","page":"Core interfaces","text":"Most extensions start by deciding where new state should live:\n\nCrop for plant-level pools or stresses.\nSoil for layer-resolved soil quantities.\nDailyWeather or ClimBuf for forcing transforms and memory terms.\nOutput for diagnostics needed by analysis or losses.\n\nAfter adding state, update initialization so arrays are allocated consistently for CPU/GPU workflows.","title":"State-first extension pattern"},{"category":"section","location":"extending/core_interfaces/#In-place-process-APIs","page":"Core interfaces","text":"The package follows mutating process functions (with !) that update pre-allocated state. This avoids repeated allocations during long rollouts and is important for training performance.","title":"In-place process APIs"},{"category":"section","location":"introduction/basic_concepts/#Basic-concepts","page":"Basic concepts","text":"NeuralCrop.jl represents crop growth as a coupled set of daily process updates. The core state is stored in mutable containers for climate buffers, crop pools, soil pools, management calendars, photosynthesis variables, potential evapotranspiration variables, and output arrays.","title":"Basic concepts"},{"category":"section","location":"introduction/basic_concepts/#Gridded-crop-simulation","page":"Basic concepts","text":"The package is built around batches of grid cells. Most state variables are arrays whose last dimension indexes grid cells. This design makes it possible to run many locations at once and to move state between CPU and GPU devices with a device function.","title":"Gridded crop simulation"},{"category":"section","location":"introduction/basic_concepts/#Process-based-and-hybrid-components","page":"Basic concepts","text":"NeuralCrop supports two related model modes:\n\nProcess-based simulations use explicit crop, soil, water, carbon, and nitrogen process functions.\nHybrid simulations replace selected process rates or tendencies with neural emulators while preserving the surrounding physical model structure.","title":"Process-based and hybrid components"},{"category":"section","location":"introduction/basic_concepts/#Daily-time-stepping","page":"Basic concepts","text":"The main simulation routines advance state one day at a time. Each day reads climate forcing, updates snow and climate buffers, handles cultivation and harvest callbacks, computes crop physiology, updates soil water and biogeochemistry, and writes selected output variables.","title":"Daily time stepping"},{"category":"section","location":"introduction/basic_concepts/#External-data","page":"Basic concepts","text":"NeuralCrop relies on climate, management, soil, and LPJmL-derived initial-condition data. The repository includes small example files, but large-scale production forcing data should be obtained from the original data providers and cited accordingly.","title":"External data"},{"category":"section","location":"processes/crop/photosynthesis/#Photosynthesis","page":"Photosynthesis","text":"Photosynthesis routines compute gross carbon gain and related variables from absorbed radiation, day length, temperature, CO2, crop parameters, and temperature stress.","title":"Photosynthesis"},{"category":"section","location":"processes/crop/photosynthesis/#C3-photosynthesis","page":"Photosynthesis","text":"photosynthesis_C3! is used for C3 crop simulations such as wheat.","title":"C3 photosynthesis"},{"category":"section","location":"processes/crop/photosynthesis/#C4-photosynthesis","page":"Photosynthesis","text":"photosynthesis_C4! is used for C4 crop simulations such as maize.","title":"C4 photosynthesis"},{"category":"section","location":"processes/crop/photosynthesis/#Hybrid-photosynthesis","page":"Photosynthesis","text":"Hybrid routines can use neural components to emulate selected photosynthesis-related quantities such as lambda or vmax while preserving the surrounding daily crop update.","title":"Hybrid photosynthesis"},{"category":"section","location":"processes/soil/overview/#Soil-processes","page":"Overview","text":"Soil processes update water, carbon, nitrogen, temperature, and snow-coupled state variables.\n\nThe soil state includes layer-wise soil water, litter carbon and nitrogen, fast and slow carbon and nitrogen pools, nitrate, ammonium, runoff, percolation, evaporation, and snow variables.","title":"Soil processes"},{"category":"section","location":"processes/soil/overview/#Layer-structure","page":"Overview","text":"Many soil arrays are stored as (layers, cells). Litter and mineral soil pools can use different layer counts.","title":"Layer structure"},{"category":"section","location":"extending/adding_process_modules/#Adding-process-modules","page":"Adding process modules","text":"This page describes a practical workflow for adding a new process to NeuralCrop.","title":"Adding process modules"},{"category":"section","location":"extending/adding_process_modules/#1.-Choose-the-process-domain","page":"Adding process modules","text":"Put new routines under the appropriate domain:\n\nsrc/physics/crop for crop physiology and management.\nsrc/physics/soil for soil water/biogeochemistry/temperature.\nsrc/physics/climate for forcing buffers and climate transforms.","title":"1. Choose the process domain"},{"category":"section","location":"extending/adding_process_modules/#2.-Add-state-and-parameters","page":"Adding process modules","text":"If the process needs new state variables, update:\n\nsrc/physics/variables/define_structs.jl\nsrc/physics/variables/init_struct.jl\noptional output fields in src/physics/variables/output.jl\n\nKeep array shapes consistent with existing conventions ((layers, cells) or (cells,)).","title":"2. Add state and parameters"},{"category":"section","location":"extending/adding_process_modules/#3.-Implement-a-mutating-process-function","page":"Adding process modules","text":"Use an in-place function signature ending in !, and update only the state owned by that process. Avoid hidden allocation inside day loops when possible.","title":"3. Implement a mutating process function"},{"category":"section","location":"extending/adding_process_modules/#4.-Wire-into-the-daily-driver","page":"Adding process modules","text":"Register the new process call in:\n\nsrc/simulations/daily_crop_C3.jl\nsrc/simulations/daily_crop_C4.jl\nand, if needed, src/training/daily_crop_C3_training.jl\n\nKeep the call order physically consistent with existing dependencies (for example, climate update before phenology, and phenology before harvest logic).","title":"4. Wire into the daily driver"},{"category":"section","location":"extending/adding_process_modules/#5.-Export-and-document","page":"Adding process modules","text":"Export the new function in src/NeuralCrop.jl if it is public, then add or update pages in docs/src/processes to describe the new behavior.","title":"5. Export and document"},{"category":"section","location":"introduction/software_architecture/#Software-architecture","page":"Software architecture","text":"NeuralCrop.jl is organized around process domains. The top-level module includes source files from src/physics, src/hybrid, src/neural_network, src/training, src/simulations, and src/utilities.","title":"Software architecture"},{"category":"section","location":"introduction/software_architecture/#Source-layout","page":"Software architecture","text":"physics/variables defines state containers, parameters, initialization, callbacks, and output buffers.\nphysics/climate handles climate reading, climate buffers, snow, and temperature stress.\nphysics/crop implements crop physiology, phenology, management, photosynthesis, carbon allocation, nitrogen demand and uptake, transpiration, interception, and harvesting.\nphysics/soil implements pedotransfer functions, soil temperature, water, carbon, nitrogen, evaporation, infiltration, and percolation.\nhybrid contains neural-network replacements for selected crop and soil process components.\nneural_network defines MLP/NODE wrappers, custom Euler solvers, emulator functions, losses, and training loops.\nsimulations contains daily C3 and C4 crop drivers.","title":"Source layout"},{"category":"section","location":"introduction/software_architecture/#Data-movement","page":"Software architecture","text":"Most initialization and data-loading functions accept a device argument. Passing Array keeps arrays on CPU, while GPU-oriented device functions can move compatible arrays to accelerator memory.","title":"Data movement"},{"category":"section","location":"introduction/software_architecture/#Public-interface","page":"Software architecture","text":"The package exports model state types, parameters, initialization routines, daily simulation drivers, process functions, neural emulator functions, training loops, and selected utilities. See API index for a generated index.","title":"Public interface"},{"category":"section","location":"processes/climate/overview/#Climate-processes","page":"Overview","text":"Climate routines read daily forcing and update rolling climate buffers used by phenology, temperature stress, snow, and soil-temperature calculations.","title":"Climate processes"},{"category":"section","location":"processes/climate/overview/#Daily-forcing","page":"Overview","text":"The daily weather state includes temperature, precipitation, shortwave radiation, longwave radiation, normalized forcing variables, daily CO2, and annual CO2.","title":"Daily forcing"},{"category":"section","location":"processes/climate/overview/#Climate-buffers","page":"Overview","text":"Climate buffers store recent temperatures, monthly temperatures, annual temperatures, minimum-temperature summaries, and vernalization-related variables.","title":"Climate buffers"},{"category":"section","location":"processes/climate/overview/#Snow","page":"Overview","text":"Snow routines update snowpack, snow height, and snow fraction before the crop and soil processes are evaluated.","title":"Snow"},{"category":"section","location":"processes/crop/carbon_nitrogen/#Crop-carbon-and-nitrogen","page":"Carbon and nitrogen","text":"Crop carbon and nitrogen routines translate photosynthesis into biomass growth, pool allocation, respiration, nitrogen demand, and nitrogen uptake.","title":"Crop carbon and nitrogen"},{"category":"section","location":"processes/crop/carbon_nitrogen/#Carbon","page":"Carbon and nitrogen","text":"Carbon routines compute respiration, carbon allocation among crop pools, storage carbon, vegetation carbon, and biomass.","title":"Carbon"},{"category":"section","location":"processes/crop/carbon_nitrogen/#Nitrogen","page":"Carbon and nitrogen","text":"Nitrogen routines calculate total demand, leaf demand, uptake from soil pools, and nitrogen stress terms that feed back on crop growth.","title":"Nitrogen"},{"category":"section","location":"processes/utilities/overview/#Utilities","page":"Utilities","text":"Utility functions support data loading, normalization, plotting, and date/index conversion.","title":"Utilities"},{"category":"section","location":"processes/utilities/overview/#NetCDF-loading","page":"Utilities","text":"Utilities load one-dimensional and multi-dimensional variables from NetCDF files for selected time ranges or grid locations.","title":"NetCDF loading"},{"category":"section","location":"processes/utilities/overview/#Normalization","page":"Utilities","text":"Normalization helpers support min-max and z-score style transformations used by neural-network inputs and training targets.","title":"Normalization"},{"category":"section","location":"processes/utilities/overview/#Visualization","page":"Utilities","text":"Visualization utilities include helpers for plotting loss curves and loading output data for analysis.","title":"Visualization"},{"category":"section","location":"running/training/#Training","page":"Training","text":"Training routines roll the crop model forward through time and differentiate losses through the hybrid dynamics.","title":"Training"},{"category":"section","location":"running/training/#Rollout-training","page":"Training","text":"train_loop_rollout! trains over daily rollout windows. Each batch loads a subset of grid cells, initializes state, spins up climate buffers, evaluates the rollout loss, and updates neural-network parameters with Optimisers.jl.","title":"Rollout training"},{"category":"section","location":"running/training/#Losses","page":"Training","text":"loss_crop_rollout! compares normalized model outputs against LPJmL-derived targets. The current loss combines terms for photosynthesis variables, GPP, vegetation carbon, soil carbon pools, and soil water.","title":"Losses"},{"category":"section","location":"running/training/#Practical-notes","page":"Training","text":"Training is memory intensive because it differentiates through model dynamics. Start with small batches and short rollouts before scaling to larger spatial domains or longer periods.","title":"Practical notes"},{"category":"section","location":"api_index/#API-index","page":"API index","text":"This page provides a compact, module-oriented API map in the style of modern Julia model documentation. The goal is to help users locate interfaces quickly without reading a long, function-by-function manual.","title":"API index"},{"category":"section","location":"api_index/#Full-symbol-index","page":"API index","text":"Modules = [NeuralCrop]","title":"Full symbol index"},{"category":"section","location":"api_index/#Workflow-entry-points","page":"API index","text":"Use these quick routes when you are trying to complete a concrete task.","title":"Workflow entry points"},{"category":"section","location":"api_index/#I-want-to-run-a-simulation","page":"API index","text":"Drivers: daily_crop_C3!, daily_crop_C4!\nSetup and state allocation: init_structs!, init_crop, init_soil, init_climbuf, init_output\nData loading: DataLoader, DataLoader_winter_wheat, InitilDataLoader, ClimateDataLoader\nOutput extraction: output_predict!, output_finetune!\nJump links: Simulation outputs and utilities, Neural and simulation drivers","title":"I want to run a simulation"},{"category":"section","location":"api_index/#I-want-to-train-hybrid-components","page":"API index","text":"Training loop and loss: train_loop_rollout!, train_loop_winter_wheat_rollout!, loss_crop_rollout!, daily_crop_C3_training!\nNeural wrappers and emulators: NODE, MLP, neural_lambda, neural_vmax, neural_stoc, neural_allocation, neural_moisture\nHybrid process hooks: crop_carbon_hybrid!, hybrid_photos_C3!, hybrid_photos_C4!, hybrid_litc, hybrid_soilc, hybrid_litn, hybrid_soiln\nJump links: Hybrid, neural, and training, Neural and simulation drivers","title":"I want to train hybrid components"},{"category":"section","location":"api_index/#I-want-to-add-or-modify-a-process","page":"API index","text":"Climate process entry points: readclimate!, update_climbuf!, snow!, temp_stress\nCrop process entry points: photosynthesis_C3!, phenology_crop!, crop_carbon!, crop_nitrogen!, harvest_crop!\nSoil process entry points: soil_water!, soil_carbon!, soil_nitrogen!, pedotransfer!, soiltemp_lag!\nJump links: Climate and crop processes, Soil and hybrid processes","title":"I want to add or modify a process"},{"category":"section","location":"api_index/#I-want-to-inspect-model-state-and-parameters","page":"API index","text":"Parameter presets: lpjmlparams, photoparams, soilparams, snowparams, cft1, cft2, cft3, cft4\nState containers: Crop, Soil, ClimBuf, DailyWeather, Photos, Output\nUnit and normalization helpers: deg2rad, ppm2Pa, z_score_norm, apply_z_score\nJump links: Types and parameter presets, Variables and initialization","title":"I want to inspect model state and parameters"},{"category":"section","location":"api_index/#Exported-API-overview","page":"API index","text":"This section lists the main exported symbols even when some of them do not yet have full docstrings.","title":"Exported API overview"},{"category":"section","location":"api_index/#Types-and-parameter-presets","page":"API index","text":"Use these to configure crop functional types, physical parameters, and model state containers before running simulations.\n\nLPJmLParams, PftParameters, PhotoParams, SoilParams, SnowParams\nPhotos, PetPar, DailyWeather, ClimBuf, CO2, Crop, Calendar, Managed_land, Soil, Output\nlpjmlparams, photoparams, soilparams, snowparams\ncft1, cft2, cft3, cft4\nDetailed section: Variables and initialization","title":"Types and parameter presets"},{"category":"section","location":"api_index/#Initialization-and-data","page":"API index","text":"Use these to build model-ready batches and allocate in-memory state on CPU/GPU backends.\n\ninit_structs!, init_climbuf, init_crop, init_pet, init_soil, init_data_norm, init_output\nInitilDataLoader, ClimateDataLoader, DataLoader, DataLoader_winter_wheat\nDetailed section: Variables and initialization","title":"Initialization and data"},{"category":"section","location":"api_index/#Climate,-crop,-and-soil-processes","page":"API index","text":"Use these process kernels to update daily forcing, crop growth, soil water, and soil biogeochemistry.\n\nClimate: annual_climbuf!, daily_climbuf!, infil_perc!, spin_up_climbuf!, update_climbuf!, readclimate!, snow!\nCrop radiation and water: albedo!, petpar!, apar_crop!, apar_crop_maize!, transpiration!, interception!\nCrop physiology: photosynthesis_C3!, photosynthesis_C4!, carbon_allocation!, respiration!, phenology_crop!, lai_crop!, lai_deficit!, cultivate!, harvest_crop!, fertilizer!\nCrop nutrients: crop_nitrogen!, crop_nitrogen_old!, ndemand_crop!, nuptake_crop!\nSoil processes: soiltemp_lag!, pedotransfer!, update_lit_tillage!, update_lit_winter_wheat!, soil_carbon!, evaporation!, soil_water!, nitrogen_transform!, soil_nitrogen!, update_litc_tillage!, update_litn_tillage!\nShared helpers: root_distribution, temp_stress\nDetailed sections: Climate and crop processes, Soil and hybrid processes","title":"Climate, crop, and soil processes"},{"category":"section","location":"api_index/#Hybrid,-neural,-and-training","page":"API index","text":"Use these interfaces to embed neural emulators in process updates and train parameters with rollout objectives.\n\nHybrid crop/soil: crop_carbon_hybrid!, hybrid_photos_C3!, hybrid_photos_C4!, hybrid_litc, hybrid_soilc, hybrid_litn, hybrid_soiln\nNeural model wrappers and solvers: NODE, MLP, solve, SciMLEuler, SciMLEuler_litc, SciMLEuler_soilc\nNeural emulators: neural_gpp, neural_lambda, neural_vmax, neural_stoc, neural_allocation, neural_moisture, get_mlp, get_node\nTraining loop and loss: train_loop_winter_wheat_rollout!, train_loop_rollout!, loss_crop_rollout!, daily_crop_C3_training!\nDetailed section: Neural and simulation drivers","title":"Hybrid, neural, and training"},{"category":"section","location":"api_index/#Simulation-outputs-and-utilities","page":"API index","text":"Use these helpers for daily simulation entry points, output extraction, normalization, and plotting.\n\nDaily simulation drivers: daily_crop_C3!, daily_crop_C4!\nOutput aggregation: output_training!, output_predict!, output_finetune!\nUnits and normalization: deg2rad, ppm2Pa, ppm2bar, hour2day, hour2sec, degCtoK, min_max_norm, z_score_norm, apply_z_score\nPlot/data helpers: load_nc_file_one_dimension, load_nc_file_dimensions, plot_loss_curve\nDetailed section: Neural and simulation drivers","title":"Simulation outputs and utilities"},{"category":"section","location":"api_index/#API-by-source-module","page":"API index","text":"","title":"API by source module"},{"category":"section","location":"api_index/#Variables-and-initialization","page":"API index","text":"Key symbols:\n\nLPJmLParams, PftParameters, PhotoParams, SoilParams, SnowParams\nPhotos, PetPar, DailyWeather, ClimBuf, CO2, Crop, Calendar, Managed_land, Soil, Output\ninit_structs!, init_climbuf, init_crop, init_pet, init_soil, init_data_norm, init_output\nInitilDataLoader, ClimateDataLoader, DataLoader, DataLoader_winter_wheat","title":"Variables and initialization"},{"category":"section","location":"api_index/#Climate-and-crop-processes","page":"API index","text":"Key symbols:\n\nClimate: annual_climbuf!, daily_climbuf!, infil_perc!, spin_up_climbuf!, update_climbuf!, readclimate!, snow!\nRadiation and energy: albedo!, petpar!, apar_crop!, apar_crop_maize!, temp_stress\nCrop growth: photosynthesis_C3!, photosynthesis_C4!, phenology_crop!, lai_crop!, lai_deficit!, crop_carbon!, carbon_allocation!, respiration!\nManagement and water: cultivate!, harvest_crop!, fertilizer!, interception!, transpiration!\nCrop nitrogen: crop_nitrogen!, crop_nitrogen_old!, ndemand_crop!, nuptake_crop!, root_distribution","title":"Climate and crop processes"},{"category":"section","location":"api_index/#Soil-and-hybrid-processes","page":"API index","text":"Key symbols:\n\nSoil core: soiltemp_lag!, pedotransfer!, evaporation!, soil_water!, infil_perc!\nSoil carbon and nitrogen: soil_carbon!, soil_nitrogen!, nitrogen_transform!, update_lit_tillage!, update_lit_winter_wheat!, update_litc_tillage!, update_litn_tillage!\nHybrid replacements: crop_carbon_hybrid!, hybrid_photos_C3!, hybrid_photos_C4!, hybrid_litc, hybrid_soilc, hybrid_litn, hybrid_soiln","title":"Soil and hybrid processes"},{"category":"section","location":"api_index/#Neural-and-simulation-drivers","page":"API index","text":"Key symbols:\n\nNeural wrappers: NODE, MLP, SciMLEuler, SciMLEuler_litc, SciMLEuler_soilc, solve\nNeural emulators: neural_gpp, neural_lambda, neural_vmax, neural_stoc, neural_allocation, neural_moisture, get_mlp, get_node\nTraining: train_loop_rollout!, train_loop_winter_wheat_rollout!, loss_crop_rollout!, daily_crop_C3_training!\nSimulations: daily_crop_C3!, daily_crop_C4!\nOutput and plotting: output_training!, output_predict!, output_finetune!, load_nc_file_one_dimension, load_nc_file_dimensions, plot_loss_curve","title":"Neural and simulation drivers"},{"category":"section","location":"api_index/#Notes","page":"API index","text":"Some symbols may not render detailed entries yet if the corresponding source code has no docstring.\nFor workflow-level guidance, start from the Introduction, Running, Models, and Processes sections rather than this API page.\n\n```","title":"Notes"},{"category":"type","location":"api_index/#NeuralCrop.PhotoParams","page":"API index","text":"Photosynthesis Parameters\n\n\n\n\n\n","title":"NeuralCrop.PhotoParams"},{"category":"section","location":"running/input_data/#Input-data","page":"Input data","text":"NeuralCrop requires external climate, soil, management, and initial-condition data. Large-scale forcing data are not bundled with the package because they originate from third-party data providers.","title":"Input data"},{"category":"section","location":"running/input_data/#Climate-forcing","page":"Input data","text":"Daily simulations use temperature, precipitation, shortwave radiation, longwave radiation, and CO2 forcing. Climate arrays are loaded into named tuples and then sliced into simulation batches with data-loader utilities.","title":"Climate forcing"},{"category":"section","location":"running/input_data/#Crop-management","page":"Input data","text":"Crop input data include sowing dates, phenological heat units, fertilizer, manure, harvest dates for winter wheat workflows, and residue fractions.","title":"Crop management"},{"category":"section","location":"running/input_data/#Soil-and-initial-state","page":"Input data","text":"Soil parameters include soil pH, saturation water content, sand and clay fractions, thermal diffusivity parameters, and soil-layer depth. Initial soil water, carbon, and nitrogen pools currently come from LPJmL-derived state data.","title":"Soil and initial state"},{"category":"section","location":"running/input_data/#Example-data","page":"Input data","text":"The repository includes small example files in examples/ and grid files in inputs/. These are intended for demonstration and testing of workflows, not for full-scale production experiments.","title":"Example data"},{"category":"section","location":"models/hybrid_model/#Hybrid-model","page":"Hybrid model","text":"Hybrid NeuralCrop simulations insert neural-network components into selected crop and soil processes.","title":"Hybrid model"},{"category":"section","location":"models/hybrid_model/#Neural-emulators","page":"Hybrid model","text":"Neural emulators are implemented with Lux layers wrapped as MLP or NODE structures. Emulator functions convert model state and forcing inputs into rate modifiers, tendencies, or pool updates.","title":"Neural emulators"},{"category":"section","location":"models/hybrid_model/#Neural-ODE-components","page":"Hybrid model","text":"Several hybrid functions use small ODE-style updates with custom Euler solvers. This keeps the neural component compatible with the daily model time step while preserving differentiability.","title":"Neural ODE components"},{"category":"section","location":"models/hybrid_model/#Training-context","page":"Hybrid model","text":"Hybrid components are trained through rollout losses, where the full crop model is advanced through time and the neural parameters are updated from differences between model output and reference targets.","title":"Training context"},{"category":"section","location":"processes/neural_network/overview/#Neural-networks","page":"Neural networks","text":"NeuralCrop uses Lux.jl for neural-network layers and Optimisers.jl for parameter updates.","title":"Neural networks"},{"category":"section","location":"processes/neural_network/overview/#Model-wrappers","page":"Neural networks","text":"MLP wraps a Lux model for feed-forward emulators. NODE wraps a Lux model together with a solver and time span for neural ODE-style components.","title":"Model wrappers"},{"category":"section","location":"processes/neural_network/overview/#Emulator-functions","page":"Neural networks","text":"Emulator functions include neural predictions for photosynthesis-related variables, storage carbon, allocation, litter and soil carbon turnover, soil nitrogen turnover, and soil moisture.","title":"Emulator functions"},{"category":"section","location":"processes/neural_network/overview/#Custom-solvers","page":"Neural networks","text":"The package defines simple Euler-style solvers for daily updates. These are small, differentiable building blocks for neural ODE components.","title":"Custom solvers"},{"category":"section","location":"running/initialization/#Initialization","page":"Initialization","text":"NeuralCrop initialization creates typed state containers and moves their arrays to the selected device.","title":"Initialization"},{"category":"section","location":"running/initialization/#State-containers","page":"Initialization","text":"Important state containers include:\n\nClimBuf for rolling climate buffers.\nCrop and Calendar for crop state and management callbacks.\nPhotos and PetPar for photosynthesis and potential evapotranspiration variables.\nSoil for soil water, carbon, nitrogen, and snow state.\nOutput for diagnostics collected during simulations and training.","title":"State containers"},{"category":"section","location":"running/initialization/#Device-argument","page":"Initialization","text":"Initialization functions accept a device function. Use Array for CPU arrays. GPU workflows use device functions from the CUDA/LuxCUDA stack.","title":"Device argument"},{"category":"section","location":"running/initialization/#Typical-order","page":"Initialization","text":"A simulation usually loads data, builds an InitialData batch with InitilDataLoader, initializes state with init_structs!, spins up climate buffers with spin_up_climbuf!, and then calls a daily simulation driver.","title":"Typical order"},{"category":"section","location":"processes/soil/carbon_nitrogen/#Soil-carbon-and-nitrogen","page":"Carbon and nitrogen","text":"Soil carbon and nitrogen routines update litter, fast, and slow pools while accounting for crop residue inputs, decomposition, tillage transfers, and environmental modifiers.","title":"Soil carbon and nitrogen"},{"category":"section","location":"processes/soil/carbon_nitrogen/#Carbon-pools","page":"Carbon and nitrogen","text":"The model tracks litter carbon, fast carbon, slow carbon, decomposition fluxes, and heterotrophic respiration.","title":"Carbon pools"},{"category":"section","location":"processes/soil/carbon_nitrogen/#Nitrogen-pools","page":"Carbon and nitrogen","text":"The model tracks litter nitrogen, fast nitrogen, slow nitrogen, ammonium, nitrate, nitrogen inputs, and transformations.","title":"Nitrogen pools"},{"category":"section","location":"processes/soil/carbon_nitrogen/#Hybrid-biogeochemistry","page":"Carbon and nitrogen","text":"Hybrid functions can emulate decomposition or turnover components while retaining the larger pool-update structure.","title":"Hybrid biogeochemistry"},{"category":"section","location":"introduction/mathematical_formulation/#Mathematical-formulation","page":"Mathematical formulation","text":"NeuralCrop.jl follows a daily, process-based crop modeling structure inspired by LPJmL. The full equations are distributed across process modules. This page summarizes the high-level coupling.","title":"Mathematical formulation"},{"category":"section","location":"introduction/mathematical_formulation/#State-vector","page":"Mathematical formulation","text":"For each grid cell, the model state contains crop carbon and nitrogen pools, leaf area, phenological state, soil water by layer, soil carbon and nitrogen pools, snow state, climate buffers, and output diagnostics.","title":"State vector"},{"category":"section","location":"introduction/mathematical_formulation/#Daily-update","page":"Mathematical formulation","text":"A daily update can be viewed schematically as\n\nx_t+1 = F_theta(x_t u_t p)\n\nwhere x_t is the model state, u_t is daily forcing, p contains crop and soil parameters, and F_theta is either a purely process-based update or a hybrid update with trainable neural-network components.","title":"Daily update"},{"category":"section","location":"introduction/mathematical_formulation/#Hybrid-replacement","page":"Mathematical formulation","text":"Hybrid components replace selected process tendencies or rate modifiers:\n\nr_t = N_theta(z_t)\n\nwhere z_t contains normalized state and forcing inputs. The neural output is then inserted into the physical update, preserving mass-flow structure where the surrounding process function enforces it.","title":"Hybrid replacement"},{"category":"section","location":"introduction/mathematical_formulation/#Training-objective","page":"Mathematical formulation","text":"Training routines compare normalized model outputs against reference targets, including crop productivity, vegetation carbon, soil carbon pools, and soil water. The rollout loss is accumulated over daily windows to train neural components inside the model dynamics.","title":"Training objective"},{"category":"section","location":"processes/hybrid/overview/#Hybrid-components","page":"Hybrid components","text":"Hybrid components live in src/hybrid and replace selected process-based calculations with neural-network outputs.","title":"Hybrid components"},{"category":"section","location":"processes/hybrid/overview/#Crop-hybrid-components","page":"Hybrid components","text":"Crop hybrid routines cover photosynthesis and crop carbon related processes.","title":"Crop hybrid components"},{"category":"section","location":"processes/hybrid/overview/#Soil-hybrid-components","page":"Hybrid components","text":"Soil hybrid routines cover soil water, soil carbon, and soil nitrogen updates.","title":"Soil hybrid components"},{"category":"section","location":"processes/hybrid/overview/#Design-goal","page":"Hybrid components","text":"The goal is to train data-driven components inside the physical crop model, rather than fitting isolated post-processing corrections.","title":"Design goal"},{"category":"section","location":"processes/soil/water/#Soil-water","page":"Water","text":"Soil water routines compute how precipitation, irrigation, infiltration, percolation, evaporation, and transpiration affect water content in each soil layer.","title":"Soil water"},{"category":"section","location":"processes/soil/water/#Pedotransfer","page":"Water","text":"pedotransfer! estimates hydraulic properties from soil texture and soil depth variables.","title":"Pedotransfer"},{"category":"section","location":"processes/soil/water/#Fluxes","page":"Water","text":"Water fluxes include infiltration, percolation, layer outflow, surface runoff, and transpiration demand from crop roots.","title":"Fluxes"},{"category":"section","location":"processes/soil/water/#Hybrid-water","page":"Water","text":"Hybrid simulations can replace part of the soil water update with a neural moisture emulator.","title":"Hybrid water"},{"category":"section","location":"#NeuralCrop.jl","page":"Home","text":"NeuralCrop.jl is a framework for differentiable, global gridded crop modeling that combines process-based crop and soil dynamics with trainable neural components. It is designed for hybrid Earth-system modeling workflows where physical structure and machine-learning flexibility are both required.\n\nThe package targets daily time-step simulations over many grid cells and supports CPU/GPU workflows through Julia's array and accelerator ecosystem.\n\nwarning: Under development\nNeuralCrop.jl is under active development. At this stage, spin-up simulations for equilibrium soil carbon, nitrogen, and water states are not yet supported. These initial soil states are derived from LPJmL outputs.","title":"NeuralCrop.jl"},{"category":"section","location":"#Installation","page":"Home","text":"NeuralCrop.jl is not yet registered in the Julia General registry. You can install it directly from GitHub by typing ] in the Julia REPL and running:\n\npkg> add https://github.com/yunan-l/NeuralCrop.jl.git\n\nFor development and examples, clone the repository and instantiate the project:\n\ngit clone https://github.com/yunan-l/NeuralCrop.jl.git\ncd NeuralCrop.jl\njulia --project=. -e \"import Pkg; Pkg.instantiate()\"\n\ncompat: Julia 1.10 is recommended\nNeuralCrop.jl currently targets Julia 1.10.x.","title":"Installation"},{"category":"section","location":"#Quick-start","page":"Home","text":"A typical NeuralCrop workflow has four steps:\n\nLoad climate, crop management, soil, and LPJmL-derived initial-state data.\nSelect a crop functional type and initialize model state containers on CPU or GPU.\nRun a daily crop simulation with either process-based or hybrid components.\nSave or analyze model outputs such as yield, GPP, LAI, soil water, and soil carbon pools.\n\nThe repository includes a small demonstration dataset and a Jupyter notebook in examples/ for wheat simulations over 10 grid cells.\n\nusing NeuralCrop\n\n# 1. Activate package environment (outside Julia):\n# julia --project=. -e \"import Pkg; Pkg.instantiate()\"\n#\n# 2. Run the demonstration workflow:\n# open examples/wheat_rainfed.ipynb\n#\n# 3. For scripted runs, use the exported pipeline:\n# - load forcing and initial-condition data\n# - initialize states with init_structs!\n# - run daily_crop_C3! or daily_crop_C4!\n# - inspect output fields (yield, lai, gpp, swc, litc, ...)","title":"Quick start"},{"category":"section","location":"#Table-of-contents","page":"Home","text":"","title":"Table of contents"},{"category":"section","location":"#Introduction","page":"Home","text":"Pages = [\n    \"introduction/basic_concepts.md\",\n    \"introduction/software_architecture.md\",\n    \"introduction/mathematical_formulation.md\",\n]\nDepth = 2","title":"Introduction"},{"category":"section","location":"#Running-NeuralCrop","page":"Home","text":"Pages = [\n    \"running/installation.md\",\n    \"running/input_data.md\",\n    \"running/initialization.md\",\n    \"running/daily_simulations.md\",\n    \"running/training.md\",\n]\nDepth = 2","title":"Running NeuralCrop"},{"category":"section","location":"#Extending-NeuralCrop","page":"Home","text":"Pages = [\n    \"extending/core_interfaces.md\",\n    \"extending/adding_process_modules.md\",\n    \"extending/hybrid_components.md\",\n]\nDepth = 2","title":"Extending NeuralCrop"},{"category":"section","location":"#Models","page":"Home","text":"Pages = [\n    \"models/crop_model.md\",\n    \"models/soil_model.md\",\n    \"models/hybrid_model.md\",\n]\nDepth = 2","title":"Models"},{"category":"section","location":"#Processes","page":"Home","text":"Pages = [\n    \"processes/climate/overview.md\",\n    \"processes/crop/overview.md\",\n    \"processes/soil/overview.md\",\n    \"processes/hybrid/overview.md\",\n    \"processes/neural_network/overview.md\",\n    \"processes/utilities/overview.md\",\n]\nDepth = 2","title":"Processes"},{"category":"section","location":"#Other","page":"Home","text":"Pages = [\n    \"contributing.md\",\n    \"api_index.md\",\n    \"references.md\",\n]\nDepth = 2","title":"Other"},{"category":"section","location":"extending/hybrid_components/#Hybrid-components","page":"Hybrid components","text":"Hybrid components connect neural modules with process-based dynamics. This is the central extension path for data-constrained process improvement.","title":"Hybrid components"},{"category":"section","location":"extending/hybrid_components/#Design-pattern","page":"Hybrid components","text":"NeuralCrop hybrid components generally follow this pattern:\n\nBuild neural inputs from current state and forcing.\nPredict process modifiers or tendencies using MLP or NODE.\nApply predictions inside a physically structured state update.\nTrain via rollout losses that compare modeled trajectories to reference data.","title":"Design pattern"},{"category":"section","location":"extending/hybrid_components/#Where-to-implement","page":"Hybrid components","text":"Add model-specific hybrid logic in src/hybrid.\nAdd reusable neural wrappers or helpers in src/neural_network.\nIntegrate calls from daily simulation drivers.","title":"Where to implement"},{"category":"section","location":"extending/hybrid_components/#Parameter-and-state-flow","page":"Hybrid components","text":"The training loop passes:\n\nnn_model for architecture,\nps for trainable parameters,\nst for Lux state,\nbatch data and initialized model states.\n\nKeep this interface intact when introducing new hybrid modules so rollout training remains compatible.","title":"Parameter and state flow"},{"category":"section","location":"extending/hybrid_components/#Numerical-stability","page":"Hybrid components","text":"When adding hybrid components:\n\nscale inputs and targets carefully,\nguard against NaN/Inf in losses,\nstart with short rollouts and small batches,\nand verify that process outputs remain in physically plausible ranges.","title":"Numerical stability"}]
}
